"""The memory home: the folder `autoMemoryDirectory` names, with a folder per repository under it."""
import json
import os
import pathlib
import re
import subprocess


def _git(cwd, *args):
    run = subprocess.run(["git", "-C", cwd, *args], capture_output=True, text=True)
    return run.stdout.strip() if run.returncode == 0 else None


def main_checkout(cwd):
    """The main checkout of the repository holding cwd, which a worktree shares; None outside one."""
    if not isinstance(cwd, str) or not os.path.isdir(cwd):
        return None
    common = _git(cwd, "rev-parse", "--path-format=absolute", "--git-common-dir")
    if not common:
        return None
    common = pathlib.Path(common)
    return str(common.parent) if common.name == ".git" else _git(cwd, "rev-parse", "--show-toplevel")


def repository(cwd):
    """The repository's folder name: the origin's name, else the main checkout's folder name."""
    root = main_checkout(cwd)
    if not root:
        return None
    url = _git(root, "config", "--get", "remote.origin.url") or ""
    name = re.split(r"[/:\\]", url.rstrip("/\\"))[-1]
    name = name[:-4] if name.endswith(".git") else name
    return name or os.path.basename(root) or None


def _setting(path):
    try:
        with open(path, encoding="utf-8") as handle:
            value = json.load(handle).get("autoMemoryDirectory")
    except (OSError, ValueError, AttributeError):
        return None
    if not isinstance(value, str) or not value:
        return None
    value = os.path.expanduser(value)
    return value if os.path.isabs(value) else None


def home(cwd, config):
    """The memory home: the main checkout's .claude/settings.local.json, then <config>/settings.json."""
    root = main_checkout(cwd)
    found = _setting(os.path.join(root, ".claude", "settings.local.json")) if root else None
    return found or _setting(os.path.join(str(config), "settings.json"))


